with filtered as (select *, round(duration_sec, 2) as duration_sec_rounded, round(duration_sec, 0) as duration_sec_rounded_2 from web_events where page is not null and to_date(event_time) >= '2024-12-04'), joined as (select a.id, a.session_id, a.event_type, a.duration_sec, a.duration_sec_rounded, a.duration_sec_rounded_2, d.browser, d.device, d.country from filtered a left join sessions d on a.session_id = d.id where d.device = 'tablet'), with_dims as (select a.id, a.session_id, a.event_type, a.duration_sec_rounded, a.device, a.country, b.device as session_device, b.browser as session_browser from joined a left join sessions b on a.session_id = b.id), metrics as (select id, session_id, event_type, duration_sec_rounded, device, session_browser, min(duration_sec_rounded) over (partition by country) as country_min_duration_sec_rounded, row_number() over (partition by country order by duration_sec_rounded, id) as seq_no, last_value(device, true) over (partition by session_browser, event_type order by duration_sec_rounded, id rows between unbounded preceding and current row) as last_known_device from with_dims) select s.id, s.session_id, s.event_type, s.device, s.session_browser, s.seq_no, s.last_known_device, (select avg(w2.duration_sec) from web_events w2 where w2.session_id = s.session_id) as avg_web_event_duration_sec from metrics s
